import json, numpy as np
from PIL import Image, ImageDraw
spec=json.load(open('/app/output/spec.json'))
def xyz(cam,u,v,folder='initial'):
 d=np.load(f'/app/output/{folder}/depth_{cam}.npy')[-1];z=float(d[v,u]); s=spec['cameras'][cam];K=np.array(s['intrinsic_cv']);T=np.array(s['cam2world_gl']);p=np.array([(u-K[0,2])/K[0,0]*z,-(v-K[1,2])/K[1,1]*z,-z,1]);return (T@p)[:3]
if __name__=='__main__':
 for cam,points in [('right',[(184,274),(201,258),(214,243),(229,228),(275,176)]),('left',[(216,202),(231,207),(194,190),(175,145)]),('forward',[(76,158),(97,171)])]:
